import React, { useState, useEffect } from 'react';
import './Carousel.css';

const images = [
  'https://images-eu.ssl-images-amazon.com/images/G/31/img2020/fashion/WomensApparel2024/Saree/Blouses/Blouse_Corner_Header1.png',
  'https://www.soch.com/media/wysiwyg/Ivory_Elegence_Main-Strip-Banner_Desktop-min.jpg?auto=webp&format=pjpg&quality=85',
  'https://www.soch.com/media/wysiwyg/HB_Desktop-min_3.jpg',
];

function Carousel() {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isAnimating, setIsAnimating] = useState(false);

  // Automatic slide change with delay
  useEffect(() => {
    const slideInterval = setInterval(() => {
      handleNextSlide();
    }, 5000); // Change interval here (e.g., 5 seconds)

    return () => clearInterval(slideInterval);
  }, [currentSlide]);

  const handleNextSlide = () => {
    if (isAnimating) return; // Prevent new animation during transition
    setIsAnimating(true);

    setTimeout(() => {
      setCurrentSlide((prevSlide) => (prevSlide + 1) % images.length);
      setIsAnimating(false);
    }, 600); // Transition duration matches CSS
  };

  const handlePreviousSlide = () => {
    if (isAnimating) return;
    setIsAnimating(true);

    setTimeout(() => {
      setCurrentSlide((prevSlide) =>
        prevSlide === 0 ? images.length - 1 : prevSlide - 1
      );
      setIsAnimating(false);
    }, 600);
  };

  return (
    <div className="carousel">
      <div
        className="carousel-slides"
        style={{ transform: `translateX(-${currentSlide * 100}%)` }}
      >
        {images.map((image, index) => (
          <div
            key={index}
            className="slide"
            style={{ backgroundImage: `url(${image})` }}
          />
        ))}
      </div>
      <div className="carousel-controls">
        <svg
          onClick={handlePreviousSlide}
          xmlns="http://www.w3.org/2000/svg"
          width="20"
          height="20"
          fill="white"
          className="bi bi-caret-left-fill"
          viewBox="0 0 16 16"
        >
          <path d="m3.86 8.753 5.482 4.796c.646.566 1.658.106 1.658-.753V3.204a1 1 0 0 0-1.659-.753l-5.48 4.796a1 1 0 0 0 0 1.506z" />
        </svg>
        <svg
          onClick={handleNextSlide}
          xmlns="http://www.w3.org/2000/svg"
          width="20"
          height="20"
          fill="white"
          className="bi bi-caret-right-fill"
          viewBox="0 0 16 16"
        >
          <path d="m12.14 8.753-5.482 4.796c-.646.566-1.658.106-1.658-.753V3.204a1 1 0 0 1 1.659-.753l5.48 4.796a1 1 0 0 1 0 1.506z" />
        </svg>
      </div>
    </div>
  );
}

export default Carousel;
